// Minimal stand-in for @minecraft/server, enough to run the conversion code.
import fs from 'fs';
const DEF = JSON.parse(fs.readFileSync(process.env.DS_DEFS, 'utf8'));
export class BlockPermutation {
  constructor(id, states) { this.id = id; this.states = states; this.type = { id }; }
  static resolve(id, states = {}) {
    const d = DEF[id];
    if (!d) throw new Error('unknown block ' + id);
    const out = {};
    for (const [k, vals] of Object.entries(d)) out[k] = vals[0];
    for (const [k, v] of Object.entries(states)) {
      if (!(k in d)) throw new Error(`${id}: unknown state ${k}`);
      if (!d[k].some(x => x === v)) throw new Error(`${id}: bad value ${k}=${JSON.stringify(v)}`);
      out[k] = v;
    }
    return new BlockPermutation(id, out);
  }
  getState(n) { return this.states[n]; }
  getAllStates() { return { ...this.states }; }
  withState(n, v) { return BlockPermutation.resolve(this.id, { ...this.states, [n]: v }); }
}
export const world = { beforeEvents: {}, afterEvents: {} };
export const system = { run: f => f(), runTimeout: () => 0, beforeEvents: {} };
export const BlockStates = { get: () => undefined };
export const LiquidType = { Water: 'water' };
const key = l => `${l.x},${l.y},${l.z}`;
export class Dimension {
  constructor() { this.map = new Map(); }
  setBlockPermutation(l, p) { this.map.set(key(l), p); }
  getBlock(l) { return new Block(this, l); }
  getEntities() { return []; }
}
export class Block {
  constructor(dim, l) { this.dimension = dim; this.location = { ...l }; this.x = l.x; this.y = l.y; this.z = l.z; }
  get permutation() { return this.dimension.map.get(key(this.location)) ?? BlockPermutation.resolve('minecraft:air'); }
  get typeId() { return this.permutation.id; }
  get isAir() { return this.typeId === 'minecraft:air'; }
  get isLiquid() { return false; }
  get isSolid() { return false; }
  offset(o) { return new Block(this.dimension, { x: this.x + o.x, y: this.y + o.y, z: this.z + o.z }); }
  setPermutation(p) { this.dimension.setBlockPermutation(this.location, p); }
}
